// Einmalig 2026-08-23 (v3 - Aufraeumen nach v2): v2 hat tatsaechlich alle 21 Nachrichten
// gesendet (per Execution-Datenabgleich bestaetigt: 18 echte event_id, 3 Matrix-
// Rate-Limit-Fehler), aber 'Markiere gepostet' hat wegen einer $('...').item-
// Aufloesungsstoerung unter httpRequests eingebautem Batching nur fuer 1 von 21 Items
// tatsaechlich geschrieben. v3 raeumt das auf: markiert die 18 bereits erfolgreich
// gesendeten direkt (kein erneuter Versand), sendet nur die 3 tatsaechlich fehl-
// geschlagenen erneut (mit mehr Abstand, 5s statt 2s).
const ALREADY_SENT_KEYS = ["vol_10809","vol_10808","vol_10833","vol_10832","vol_10846","vol_10845","vol_10843","vol_10838","vol_10837","vol_10836","vol_10835","vol_10834","vol_10828","vol_10826","vol_10822","vol_10814","vol_10803","vol_10801"];
const NEEDS_RESEND_KEYS = ["vol_10812","vol_10805","vol_10802"];

function parseList(value) {
  if (Array.isArray(value)) return value.filter(Boolean).map(v => String(v).trim());
  if (value === null || value === undefined || value === '') return [];
  const t = String(value).trim();
  if (!t) return [];
  try { const parsed = JSON.parse(t); if (Array.isArray(parsed)) return parsed.filter(Boolean).map(v => String(v).trim()); } catch (e) {}
  return t.split(/\s*\|\s*/).filter(Boolean).map(v => String(v).trim());
}

const allRows = $input.all().map(i => i.json);
const alreadySent = allRows.filter(r => ALREADY_SENT_KEYS.includes(r.vorgangKey))
  .map(j => ({ json: { vorgangKey: j.vorgangKey, _needsResend: false } }));

const toResend = allRows.filter(r => NEEDS_RESEND_KEYS.includes(r.vorgangKey)).map(j => {
  const sentences = parseList(j.summarySentences);
  const betroffene = parseList(j.betroffene);
  const offenePunkte = parseList(j.offenePunkte);
  const unsicherheiten = parseList(j.unsicherheitenSummary);
  let msg = `📄 Neue ALLRIS-Vorlage (nachtraeglich gesendet, Matrix-Ausfall 18.-23.08.)\n\n`;
  msg += `Titel:\n${j.title || ''}\n\n`;
  msg += `Vorgangsnummer:\n${j.vorgangsnummer || ''}\n\n`;
  msg += `Link:\n${j.allrisUrl || ''}\n\n`;
  msg += `Kurzfassung:\n`;
  let summaryBlock = '';
  if (j.summaryText && String(j.summaryText).trim()) summaryBlock = String(j.summaryText).trim();
  else if (sentences.length > 0) summaryBlock = sentences.join(' ');
  else summaryBlock = '(keine Zusammenfassung)';
  summaryBlock = summaryBlock.replace(/\r\n/g, '\n').replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  msg += summaryBlock;
  msg += `\n\nEinordnung:\n`;
  msg += `- Thema: ${j.thema || '—'}\n`;
  msg += `- Betroffene: ${betroffene.join(', ') || '—'}\n`;
  msg += `- Kosten/Haushalt: ${j.kostenHaushalt || '—'}\n`;
  msg += `- Bürgerwirkung: ${j.buergerwirkung || '—'}\n`;
  if (offenePunkte.length > 0) msg += `- Offene Punkte:\n` + offenePunkte.map(p => `  • ${p}`).join('\n') + '\n';
  if (unsicherheiten.length > 0) msg += `- Unsicherheiten:\n` + unsicherheiten.map(p => `  • ${p}`).join('\n') + '\n';
  const txnId = 'sumcatchup3_' + Date.now() + '_' + (j.vorgangKey || '').replace(/[^a-zA-Z0-9]/g,'').substring(0,10);
  return { json: { vorgangKey: j.vorgangKey, summaryMessage: msg, txnId, _needsResend: true } };
});

console.log('[Matrix-Nachtrag v3] bereits gesendet (nur DB-Flag): ' + alreadySent.length + ', erneut senden: ' + toResend.length);
return [...alreadySent, ...toResend];

// Positionsbasierte Zuordnung statt $('...').item - httpRequests eingebautes Batching
// hat in v2 die automatische pairedItem-Aufloesung fuer die meisten Items zerstoert.
// Da Ein- und Ausgabereihenfolge nachweislich 1:1 erhalten bleibt (per v2-Execution-
// Diff bestaetigt), wird hier stattdessen $itemIndex direkt gegen die Eingabeliste
// dieses Zweigs verwendet.
const original = $('IF erneut senden?').all(0)[$itemIndex]?.json || {};
const item = $input.item;
const j = item.json || {};
const hasError = !!(item.error || j.error || j.__error);
const eventId = j.event_id || j.eventId || '';
const matrixSuccess = !hasError && typeof eventId === 'string' && eventId.startsWith('$');
return { json: { vorgangKey: original.vorgangKey, _sentOk: matrixSuccess, _eventId: eventId } };

// Zusammenfuehrung: bereits-gesendet-Zweig (immer markieren, direkt aus 'Baue v3
// Liste' gelesen statt ueber eine zweite Verbindung - vermeidet Doppelausfuehrung)
// + erfolgreich erneut gesendeter Zweig (nur bei _sentOk===true markieren).
const fullList = $('Baue v3 Liste').all();
const alreadySent = fullList.filter(i => i.json._needsResend === false);
const resendResults = $input.all().filter(i => i.json._sentOk === true);
const toMark = [...alreadySent, ...resendResults].map(i => ({ json: { vorgangKey: i.json.vorgangKey } }));
console.log('[Matrix-Nachtrag v3] insgesamt als gepostet zu markieren: ' + toMark.length);
return toMark;
